-- 공통 준비 코드

@SpringBootTest
@Transactional
public abstract class QuerydslTestSupport {

    @PersistenceContext protected EntityManager em;
    protected JPAQueryFactory queryFactory;

    @BeforeEach
    void setUp() {
        queryFactory = new JPAQueryFactory(em);

        Team teamA = new Team("teamA");
        Team teamB = new Team("teamB");
        em.persist(teamA);
        em.persist(teamB);

        em.persist(new Member("m1", 10, teamA));
        em.persist(new Member("m2", 20, teamA));
        em.persist(new Member("m3", 30, teamA));
        em.persist(new Member("m4", 40, teamA));
        em.persist(new Member("m5", 15, teamB));
        em.persist(new Member("m6", 25, teamB));
        em.persist(new Member("m7", 35, teamB));
        em.persist(new Member("m8", 10));      // 팀 없음
        em.persist(new Member("m9", 20));
        em.persist(new Member("m10", 30));

        em.flush();
        em.clear();
    }
}

--   이 클래스를 상속해서 쓴다
--   clear 까지가 준비다


-- 들어간 걸 확인한다

@Test
void 데이터_확인() {
    List<Tuple> rows = queryFactory
            .select(member.username, member.age, member.team.name)
            .from(member)
            .leftJoin(member.team, team)
            .orderBy(member.id.asc())
            .fetch();

    rows.forEach(t -> System.out.printf("%-4s %2d %s%n",
            t.get(member.username), t.get(member.age),
            t.get(member.team.name)));
}

