@Test
void 동점() {
    List<Tuple> rows = queryFactory
            .select(member.age, member.count())
            .from(member)
            .groupBy(member.age)
            .having(member.count().gt(1))
            .orderBy(member.age.asc())
            .fetch();

    rows.forEach(t -> System.out.println(
            t.get(member.age) + "살: " + t.get(member.count()) + "명"));
}

