@Test
void 최종() {
    Long total = queryFactory.select(member.count()).from(member).fetchOne();
    Long withTeam = queryFactory.select(member.count()).from(member)
            .where(member.team.isNotNull()).fetchOne();
    System.out.println("전체 " + total + ", 팀 있음 " + withTeam);
}

